package com.college.hospitalmanagement;
import jakarta.persistence.*;
@Entity @Table(name="rooms",uniqueConstraints=@UniqueConstraint(name="uk_room_ward_number",columnNames={"ward_id","room_number"})) public class Room{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(name="room_number",nullable=false,length=30) private String roomNumber;@ManyToOne(optional=false) @JoinColumn(name="ward_id") private Ward ward;@Column(nullable=false,length=50) private String roomType;@Column(nullable=false) private Integer capacity;@Column(nullable=false,length=20) private String status;public Long getId(){return id;}public String getRoomNumber(){return roomNumber;}public Ward getWard(){return ward;}public String getRoomType(){return roomType;}public Integer getCapacity(){return capacity;}public String getStatus(){return status;}public void setRoomNumber(String v){roomNumber=v;}public void setWard(Ward v){ward=v;}public void setRoomType(String v){roomType=v;}public void setCapacity(Integer v){capacity=v;}public void setStatus(String v){status=v;}}
